function gen_terrain(ix,iy){

nx = ix-12+24*noise(ix/15+1000,iy/15+1000)
ny = iy-12+24*noise(ix/15+1000,iy/15+2000)
m = noise(nx/300,ny/300)+0.05 //mountaininess
