		h = lerp(lerp(get_height(flfl,(1-nhu)*(1-nho)),get_height(clfl,(nhu)*(1-nho)),nhu),
						 lerp(get_height(flcl,(1-nhu)*(  nho)),get_height(clcl,(nhu)*(  nho)),nhu),nho)

