// === Tab: get_col ===
function get_col(p,h,m) {
switch(p)
{
case 0: //Antarctica (pretty unrealistic)
return(color(175+5*sin(h*10+m*100),100+h*200,230)) ; break

case 8: //MADRID
	if (h < 0)
		return(color(130-30*h-max(350*h,-40),100-100*h,190-max(350*h,-50)+100*h+100*max(0,-2+3.5*noise((ix-iy)/40,(ix+iy)/4))))
	else
		return(color(60-min(30,h*100),100-h*150,140+sin(h*30)*15+min(h*500,30)+150*h-5*(ix % 4 ? 0 : 1)+5*(iy % 4 ? 0 : 1)))
break;

case 7: //FINLAND
	if (h < 0)	//water
		return(color(155-max(200*h,-15),130-30*h+max(200*h,-30)-100*h-100*max(0,-2+3.5*noise((ix-iy)/40,(ix+iy)/4)),220))
	else				//land
		return(color(120-min(25,h*200)-h*50,120-sq(h)*3000,150+min(h*500,30)-100*h-4*(ix % 4 ? 0 : 1)+4*(iy % 4 ? 0 : 1)))
break;

case 6: //Sibir
	if (h < 0)	//water
		return(color(120+min(60,-h*350),100,155-min(40,-h*1000)+h*50+100*max(0,-2+3.5*noise((ix-iy)/40,(ix+iy)/4))))
	else				//land
		return(color(45-h*5,150-h*300,150-min(100,h*200)-4*(ix % 4 ? 0 : 1)+4*(iy % 4 ? 0 : 1)))
break;

case 5: //NETHERLANDS
	if (h < 0)	//water
		return(color(150-30*h-max(200*h,-15),110-30*h+max(200*h,-30)-100*h-100*max(0,-2+3.5*noise((ix-iy)/40,(ix+iy)/4)),240+h*65))
	else				//land
		return(color(70-min(20,h*100)-h*55,200-h*600,150+min(h*500,30)+100*h-4*(ix % 4 ? 0 : 1)+4*(iy % 4 ? 0 : 1)))

case 4: //NORWAY
	if (h < 0)	//water
		return(color(150-30*h-max(200*h,-15),130-30*h+max(200*h,-30)-100*h-100*max(0,-2+3.5*noise((ix-iy)/40,(ix+iy)/4)),250))
	else				//land
		return(color(50-min(25,h*200)-h*50,120-h*300,150+min(h*500,30)-100*h-4*(ix % 4 ? 0 : 1)+4*(iy % 4 ? 0 : 1)))
break;

case 3: //MOROCCO
	if (h < 0)
		return(color(120-30*h-max(350*h,-50),150-100*h,200-max(350*h,-50)+100*h+100*max(0,-2+3.5*noise((ix-iy)/40,(ix+iy)/4))))
	else
		return(color(80-min(40,h*500)-h*50,100-h*150,150+min(h*500,30)+150*h-5*(ix % 4 ? 0 : 1)+5*(iy % 4 ? 0 : 1)))
break;

case 2: //FLORIDA
	if (h < 0)
		return(color(160-30*h+10*max(0,1+h*15),150-100*h-150*max(0,-2.25+3.5*noise((ix-iy)/40+1500,(ix+iy)/8)),255+h*500-100*max(0,1+h*15)))
	else
		return(color(120-m*20-min(60,h*300),150-h*200,100+min(h*500,30)+150*h-4*(ix % 4 ? 0 : 1)+4*(iy % 4 ? 0 : 1)))
break;

case 1: //GREECE
	if (h < 0)
		return(color(120-30*h-max(350*h,-50),150-100*h,200-max(350*h,-50)+100*h+100*max(0,-2+3.5*noise((ix-iy)/40,(ix+iy)/4))))
	else if (h > 0.01)
		return(color(100-m*50-min(20,h*100),200-h*300,150+200*h-4*(ix % 4 ? 0 : 1)+4*(iy % 4 ? 0 : 1)))
	else
		return(lerpColor(color(40,100,240-4*(ix % 4 ? 0 : 1)+4*(iy % 4 ? 0 : 1)),color(100-m*50-min(20,h*100),200-h*300,150+200*h-4*(ix % 4 ? 0 : 1)+4*(iy % 4 ? 0 : 1)),h/0.01))
	break;
}}

// === Tab: get_height ===
function get_height(p,i) {
switch (p)
{
	//antarctica
	case 0: h = l+.35-sq(abs(v-.5))*2 ; t -= i*.75 ; break;
	//grece
	case 1: var h = 2.5*sq(sq(m))*abs(v-.5)+0.65*(l) ; break;
	//florida
	case 2: h = sq(m-.5)/2+l/3+2.5*sq(sq(m-.1))*abs(v-.5) ; h += 0.75*max(0,.1-abs(h))*(abs(sin(v*2*PI))-.5) ; break;
	//morocco
	case 3: h = m/5+v/10+l/2 ; h += max(0,min(1,h*10))*sin(ix/15+iy/10+m*80)/15*(sq(l+.55)+v/10) ; treeheightdeterrent += 1.5*i ; cityheightdeterrent += 1.5*i ; break;
	//norway
	case 4: h = m/5+v/10+l/1.8-.1 ; h += abs(v-.5)*max(0,h)*m*8 ; cityheightdeterrent = 2 ; t += i*(-1+sin(PI*noise(nx/15+2000,ny/15)))/5 ; break;
	//netherlands
	case 5: h = sq(m-.5)/3+l/4+2.5*sq(sq(m-.1))*abs(v-.5) ; h += .06-0.1*sq(sq(sq(sq(sq(0.025+sin(ix/150+l*3+t*5+m*4)))))) ; break;
	//sibir
	case 6: h = 2*sq(sq(m+.1))*abs(v-.5)+l*0.1+m*0.5-.15 ; cityheightdeterrent += 1.5*i ; forest += i*.02 ; t += i*(-1+sin(PI*noise(nx/15+2000,ny/15)))/5 ; break;
	//finland
	case 7: h = sq(m-.5)/4+l/5+2.5*sq(sq(m-.1))*abs(v-.5)+.1 ; h += max(-.25,min(0,50*max(0,.1-abs(h-.05)/3)*(forest))) ; forest += i*.02 ; break;
	//madrid
	case 8: h = sq(m-.05)/3+l/2+2*min(.5,sq(sq(m+.1)))*abs(v-.5) ; break;
	//case 8: h = sq(m-.1)/2+2*sq(sq(m+.1))*abs(v-.5) ; break; //accidentally made the alps
}
return(h)
}

