function setup() {
	render = 1
	c = createCanvas(render == 1 ? windowWidth : 512,render == 1 ? windowHeight : 512);
	background(100);

	ix = 0
	RW = max(windowWidth, windowHeight)
	RH = RW

	colorMode(HSB,255)
	placename = "Netherlands"
	switch (placename)
	{
		case "Antarctica": place = 0 ; break;
		case "Greece": place = 1 ; break;
		case "Florida": place = 2 ; break;
		case "Morocco": place = 3 ; break;
		case "Norway": place = 4 ; break;
		case "Netherlands": place = 5 ; break;
		case "Sibir": place = 6 ; break;
		case "Finland": place = 7 ; break;
		case "Madrid": place = 8 ; break;
	}

	ternam = ["mixed","Antarctica","Greece","Florida","Morocco","Norway","Netherlands","Sibir","Finland","Madrid"]

	termap = [0,4,6,
					  7,5,8,
					  2,1,3]
	terw = 3
	terh = 3
	treebiomecol = [color(80,255,100),color(65,200,85),color(110,120,160),color(110,120,100),color(80,180,130),color(160,100,100),color(70,200,120),color(90,175,150)]
	wallcol = [color(0,0,220),color(25,100,200),color(40,50,230),color(30,130,170),color(40,150,200),color(30,130,170),color(30,130,170),color(40,50,230)]
	roofcol = [color(0,150,250),color(10,150,250),color(20,150,250), //Greece
						color(10,100,180),color(10,100,150),color(10,100,120), //Florida
						color(10,50,145),color(10,50,130),color(10,50,115),		 //Morocco
						color(10,50,135),color(10,50,120),color(10,50,105),	   //Norway
						color(5,200,150),color(15,200,150),color(25,200,150),  //Netherlands
						color(10,50,135),color(10,50,120),color(10,50,105),		 //Sibir
						color(160,50,135),color(160,50,120),color(160,50,105), //Finland
						color(10,50,145),color(10,50,130),color(10,50,115)]    //Madrid
	//noiseSeed(11)

	if (render == 0)
	{
		rx = 0 ; ry = 0 ; rX = -512 ; rY = 0
		RH = 512 ; RW = 512
	}
	time = 0
	specplace = -1
	if (specplace > -1)
	for(i=0;i<terw*terh;i++) if (termap[i] == specplace) {humid = i % terw ; hot = floor(i/terw)}
}


function keyPressed() {

if (keyCode == 82) {ix = 0 ; noiseSeed(random(10000)) ; background(100)}
if (keyCode == 80) {saveCanvas(place+floor(random(1000))+".png", 'png')}
}

function mouseClicked() {
if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < 150 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < 255) {ix = 0 ; specplace = floor(((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-30)/25) ; noiseSeed(random(10000)) ; background(100)}
}


function drawPalettes() {
	noSmooth()
	for(iy=0;iy<9;iy++)
	{
		h = -.5+ix/1920
		stroke(get_col(iy,h+0.01*sin(h*PI*32),.25))
		line(ix,iy*windowHeight/9,ix,(iy+1)*windowHeight/9,ix)
	}
	ix ++
}


function draw() {

	if (render == 1)
	{
	for(i=0;i<9;i++)
	{
		fill((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < 105 && abs((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-(15+i*25)) < 10 ? color(20,00,250) : color(20,50,200))
		stroke(specplace == i-1 ? color(80,255,255) : color(20,100,50))
		rect(5,5+i*25,100,20)
		noStroke()
		fill(color(20,100,50))
		text(ternam[i],10,22+i*25)
	}

	noSmooth()
	noFill()

	for(var nn = 0;nn<5;nn++)
	{
		if (ix++ < RW)
		for(iy=0;iy<RH;iy++)
		{
			gen_terrain(ix,iy)

			if (h*80 > 1)
			line(windowWidth/2+ix-iy,ix/2+iy/2-80*h,windowWidth/2+ix-iy,ix/2+iy/2)
			else
			point(windowWidth/2+ix-iy,ix/2+iy/2)
		}
	}}
	else
	{
		time ++

		if ((time%100) == 0)
		{
		clear()
		for(rx=0;rx<RW;rx++)
		{
			for(ry=0;ry<RH+40;ry++)
			{
				if (rX >= 0) {ix = (ry+rY)+(rx+rX)/2+10000 ; iy = (ry+rY)-(rx+rX)/2+10000}
				else {ix = ry*16+rx*8+10000 ; iy = ry*16-rx*8+10000}

				gen_terrain(ix,iy)

				if (h*80 > 1 && rX >= 0)
				line(rx,ry-80*h,rx,ry)
				else
				point(rx,ry)
			}
			ix ++
		}
	saveCanvas("Worldbit "+rX/RW+"-"+rY/RW+".png","png")
	rX += RW ; if (rX >= 16*RW) {rX = 0 ; rY += RW}
	}
	}
}

